return {
  bonus: {
    hook: "attackDamage", aura: true, group: "sword.t1.got-your-back",
    run(H, actor, ctx) {
      const zone = ctx.attackerZone;
      if (!zone) return;
      const allies = H.zone.huntersIn(zone).filter(h => h.id !== actor.id);
      const selfBonus = ctx.carrierIds.includes(actor.id) && allies.length > 0;
      const allyBonus = H.zone.threatIn(zone) > 0 && allies.some(h => ctx.carrierIds.includes(h.id));
      return { resolve: selfBonus || allyBonus ? 1 : 0 };
    },
  },
};
